	if (!pesos) return null;
	const entradas = Object.entries(pesos).filter(([, peso]) => (peso ?? 0) > 0);
	const total = entradas.reduce((soma, [, peso]) => soma + (peso ?? 0), 0);
	if (total <= 0) return null;
